enum ClientCertificateFixtures {
    static let authority = Data(base64Encoded: "")!
    static let signing = Data(base64Encoded: "")!
    static let notSigning = Data(base64Encoded: "")!

    static func subject(of der: Data) -> Data {
        var fields = DERItem.read(der).first?.children.first?.children ?? []
        if fields.first?.tag == 0xA0 { fields.removeFirst() }
        return fields[4].whole
    }
}
